package com.campusmart.controller;
import com.campusmart.entity.*; import com.campusmart.repository.*; import com.campusmart.service.UserService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/wishlist") public class WishlistController {private final WishlistItemRepository r;private final ProductRepository p;private final UserService u;public WishlistController(WishlistItemRepository r,ProductRepository p,UserService u){this.r=r;this.p=p;this.u=u;}@GetMapping public List<WishlistItem> get(Authentication a){return r.findByUserId(Long.valueOf(a.getName()));}@PostMapping public WishlistItem add(@RequestBody Map<String,Long> b,Authentication a){Long uid=Long.valueOf(a.getName()),pid=b.get("productId");return r.findByUserIdAndProductId(uid,pid).orElseGet(()->{WishlistItem w=new WishlistItem();w.setUser(u.get(uid));w.setProduct(p.findById(pid).orElseThrow(()->new IllegalArgumentException("Product not found")));return r.save(w);});}@DeleteMapping("/{id}") public void delete(@PathVariable Long id,Authentication a){WishlistItem w=r.findById(id).orElseThrow(()->new IllegalArgumentException("Wishlist item not found"));if(!w.getUser().getId().equals(Long.valueOf(a.getName())))throw new IllegalArgumentException("Forbidden");r.delete(w);}}
